    <header className="h-16 bg-[var(--color-desk)] border-b border-stone-800 px-6 flex items-center justify-between text-white shadow-lg">
      <div className="flex items-center gap-2">
        <span className="text-xl font-bold tracking-tight text-amber-200">booktodotask</span>
        <span className="text-[10px] px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-300 border border-amber-500/30">3D Workspace</span>
      </div>

      {/* Tabs */}
      <nav className="flex gap-2 bg-stone-900/60 p-1.5 rounded-xl border border-stone-700/50">
        {tabs.map((tab) => {
          const Icon = tab.icon;
          const isActive = activeTab === tab.id;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-sm font-medium transition-all ${
                isActive
                  ? 'bg-amber-600 text-white shadow-md'
                  : 'text-stone-400 hover:text-stone-200 hover:bg-stone-800/50'
              }`}
            >
              <Icon size={16} />
              {tab.label}
            </button>
          );
        })}
      </nav>

      {/* Auth / Drive Indicator */}
      <div className="flex items-center gap-3">
        <div className="flex items-center gap-1.5 text-xs text-stone-400 bg-stone-900/80 px-3 py-1.5 rounded-lg border border-stone-800">
          {isGoogleConnected ? (
            <>
              <Cloud size={15} className="text-emerald-400" />
              <span>Drive Linked</span>
            </>
          ) : (
            <>
              <CloudOff size={15} className="text-amber-500" />
              <span>Local Storage</span>
            </>
          )}
        </div>
      </div>
    </header>
  );
}
